module state_machine (
        input clk,
        input reset,
        input b,
        output reg z);parameter P0=0, P1=1, P2=2, P3=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= P0;
		else 
			state <= next;


	always_comb begin
		case(state)
			P0: next = b ? P2 : P1;
			P1: next = b ? P0 : P3;
			P2: next = b ? P3 : P1;
			P3: next = b ? P0 : P2;
			default: next = 'x;
		endcase
	end

	assign z = (state == P0 || state == P2 || state == P3);

endmodule

