module top_module(
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    wrfull
);input aclr;
input [31:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output reg [31:0] q;  // Change wire to reg
output rdempty;
output wrfull;

reg [31:0] fifo_mem [0:63];
reg [5:0] wr_ptr;
reg [5:0] rd_ptr;
wire [5:0] nxt_wr_ptr;
wire [5:0] nxt_rd_ptr;
wire [5:0] fifo_count;
reg [5:0] fifo_count_reg;

assign nxt_wr_ptr = wr_ptr + 1;
assign nxt_rd_ptr = rd_ptr + 1;
assign fifo_count = wr_ptr - rd_ptr;

always @(posedge wrclk) begin
    if (aclr) begin
        wr_ptr <= 6'b0;
    end else if (wrreq && ~wrfull) begin
        fifo_mem[wr_ptr] <= data;
        wr_ptr <= nxt_wr_ptr;
    end
end

always @(posedge rdclk) begin
    if (aclr) begin
        rd_ptr <= 6'b0;
    end else if (rdreq && ~rdempty) begin
        q <= fifo_mem[rd_ptr];
        rd_ptr <= nxt_rd_ptr;
    end
end

always @(posedge wrclk or posedge rdclk) begin
    fifo_count_reg <= fifo_count;
end

assign rdempty = (fifo_count_reg == 6'b0);
assign wrfull = (fifo_count_reg == 6'b111111);

endmodule

module shift_register(
    input clk,
    input rst,
    input shift_dir,
    input shift_in,
    output reg [7:0] shift_out
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst)
        shift_reg <= 8'b00000000;
    else if (shift_dir)
        shift_reg <= {shift_reg[6:0], shift_in};
    else
        shift_reg <= {shift_in, shift_reg[7:1]};
end

assign shift_out = shift_reg;

endmodule

