description:
Design a phase-locked loop (PLL) that synchronizes an output clock signal (out) to a reference clock signal (ref_clk) while achieving a specified output frequency through frequency multiplication and division. The PLL utilizes a phase detector to compare the phases of the reference and desired output signals, a charge pump to adjust the control voltage for the voltage-controlled oscillator (VCO), and a loop filter to stabilize the control voltage. The VCO generates a frequency based on the control voltage, which is then divided down to produce the final output clock signal at the desired frequency and phase alignment. The module facilitates clock recovery and frequency synthesis for various digital applications.
module top_module(
  input ref_clk, // reference frequency signal with frequency f_ref
  input out_clk, // desired output frequency signal with frequency f_out
  output reg out // output signal with desired frequency and phase
);

code:
module top_module(
  input ref_clk, // reference frequency signal with frequency f_ref
  input out_clk, // desired output frequency signal with frequency f_out
  output reg out // output signal with desired frequency and phase
);parameter N = 10; // multiplication factor of the PLL
parameter M = 5; // division factor of the PLL
parameter C = 8; // number of bits used to represent the phase of the output signal

reg [C-1:0] phase; // phase accumulator
reg [C-1:0] phase_diff; // phase difference between ref_clk and out_clk
reg [C-1:0] phase_diff_accum; // accumulated phase difference
reg [C-1:0] control_voltage; // control voltage for VCO
reg [C-1:0] vco_phase; // phase of VCO
reg [C-1:0] vco_freq; // frequency of VCO

// Define PFD
always @(posedge ref_clk or posedge out_clk) begin
  if (ref_clk && !out_clk) begin
    phase_diff <= phase_diff + {1'b0, phase};
  end else if (!ref_clk && out_clk) begin
    phase_diff <= phase_diff - {1'b0, phase};
  end
end

// Define charge pump
always @* begin
  if (phase_diff_accum > 0) begin
    control_voltage <= control_voltage + 1;
    phase_diff_accum <= phase_diff_accum - 1;
  end else if (phase_diff_accum < 0) begin
    control_voltage <= control_voltage - 1;
    phase_diff_accum <= phase_diff_accum + 1;
  end
end

// Define frequency divider
always @(posedge ref_clk) begin
  if (vco_freq == M-1) begin
    vco_freq <= 0;
  end else begin
    vco_freq <= vco_freq + 1;
  end
end

// Define loop filter
always @* begin
  phase_diff_accum <= phase_diff_accum + phase_diff;
  control_voltage <= control_voltage + (phase_diff_accum >> (C-4));
end

// Define VCO
always @(posedge ref_clk) begin
  vco_phase <= vco_phase + {1'b0, (N*vco_freq) >> (C-8)};
end

// Define phase detector
always @(posedge ref_clk) begin
  phase <= phase + {1'b0, (N*vco_freq) >> (C-8)};
  if (phase >= out_clk) begin
    out <= 1;
    phase <= phase - out_clk;
  end else begin
    out <= 0;
  end
end

endmodule

