module top_module (
        input clk,
        input reset,
        input w,
        output reg z);parameter A=0, B=1, C=2, D=3, E=4, F=5;
	reg [2:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= A;
		else 
			state <= next;


	always_comb begin
		case(state)
			A: next = w ? C : B;
			B: next = w ? E : D;
			C: next = w ? A : F;
			D: next = w ? F : C;
			E: next = w ? D : B;
			F: next = w ? E : A;
			default: next = 'x;
		endcase
	end

	assign z = (state == B || state == D || state == E);

endmodule

