module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter V=2'b00, W=2'b01, X=2'b10;

    always_comb begin
		case (state)
			V: next_state = (in1 == 0 && in2 == 1) ? W : X;
			W: next_state = (in1 == 0 && in2 == 1) ? X : V;
			X: next_state = (in1 == 0 && in2 == 1) ? V : W;
		endcase
    end

    assign out = (state == X);

endmodule

