module top_module(
    input read_clk,
    input write_clk,
    input rst_n,
    input write_en,
    input [7:0] write_addr,
    input [3:0] write_data,
    input read_en,
    input [7:0] read_addr,
    output reg [3:0] read_data,
    input [31:0] in,
    output [31:0] out
);reg [3:0] ram [7:0];

always @(posedge read_clk) begin
    if (read_en) begin
        read_data <= ram[read_addr];
    end
end

always @(posedge write_clk) begin
    if (write_en) begin
        ram[write_addr] <= write_data;
    end
end

reg [31:0] edge_detector;
reg [31:0] edge_detector_prev;

always @(posedge read_clk or negedge rst_n) begin
    if (!rst_n) begin
        edge_detector <= 32'b0;
        edge_detector_prev <= 32'b0;
    end else begin
        edge_detector_prev <= in;
        edge_detector <= (in & ~edge_detector_prev);
    end
end

assign out = edge_detector & read_data;

endmodule

