    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);reg [9:0] sum1, sum2, sum3, sum4, sum5, sum6, sum7;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum1 <= 0;
        sum2 <= 0;
        sum3 <= 0;
        sum4 <= 0;
        sum5 <= 0;
        sum6 <= 0;
        sum7 <= 0;
        valid_b <= 0;
        data_out <= 0;
