        sum1 <= sum7 + data_in;
        sum2 <= sum1;
        sum3 <= sum2;
        sum4 <= sum3;
        sum5 <= sum4;
        sum6 <= sum5;
        sum7 <= sum6;
        if (valid_a && ready_b) begin
            valid_b <= 1;
            data_out <= sum7;
        end else begin
            valid_b <= 0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

