module top_module(
    A,
    B,
    Cin,
    Cout,
    S
);// Module ports
    input A, B, Cin;
    output Cout, S;

    // Internal signals
    wire X1, X2, X3;
    wire Y1, Y2;

    //  Name  Output  Other arguments
    xor  xor0 (X1, A, B);
    xor  xor1 (X2, X1, Cin);
    and  and0 (X3, X1, Cin);
    and  and1 (Y1, A, B);
    and  and2 (Y2, X1, Cin);
    or   or0  (Cout, X3, Y1, Y2);
    assign S = X2;

endmodule

module top_module(
    input clk,
    input reset,
    input [7:0] data_in,
    input write,
    output reg [7:0] data_out,  // Changed from wire to reg
    input read,
    output empty,
    output full
);reg [7:0] buffer [0:15];
    reg [3:0] head = 0;
    reg [3:0] tail = 0;
    reg [3:0] count = 0;

    always @(posedge clk) begin
        if (reset) begin
            head <= 0;
            tail <= 0;
            count <= 0;
        end else begin
            if (write && !full) begin
                buffer[head] <= data_in;
                head <= (head == 15) ? 0 : head + 1;
                count <= count + 1;
            end
            if (read && !empty) begin
                data_out <= buffer[tail];
                tail <= (tail == 15) ? 0 : tail + 1;
                count <= count - 1;
            end
        end
    end

    assign empty = (count == 0);
    assign full = (count == 16);

endmodule

