module memory_8x8
(
    input clk,
    input rst_n,
    input wr_en,
    input [2:0] addr,
    input [7:0] data_in,
    output reg [7:0] data_out
);

reg [7:0] mem [7:0];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        mem[addr] <= 8'd0;
    else if (wr_en)
        mem[addr] <= data_in;
end

always @(posedge clk) begin
    data_out <= mem[addr];
end

endmodule

