    counter <= counter + 1;
    if (counter >= duty_cycle) begin
      pwm_out <= 0;
    end else begin
      pwm_out <= 1;
    end
  end

  assign h_bridge_out1 = (dir == 1) ? pwm_out : 0;
  assign h_bridge_out2 = (dir == 0) ? pwm_out : 0;

endmodule

