module top_module(
  input clk,
  input sclk,
  input dcc_en,
  input finish_dcc,
  input dcc_vld,
  input [15:0] dcc_data,
  output statistics_dv,
  output [15:0] statistics_do
);reg [15:0] statistics_do_reg;
reg statistics_dv_reg;
reg [4:0] dcc_cntr;
reg dcc_run;
reg dcc_finishing;
reg skip16;

assign statistics_do = statistics_do_reg;
assign statistics_dv = statistics_dv_reg;

always @ (posedge sclk) begin
  if (dcc_vld) begin
    statistics_do_reg <= dcc_data;
    statistics_dv_reg <= 1;
  end else if (dcc_finishing) begin
    statistics_dv_reg <= 1;
  end else begin
    statistics_dv_reg <= 0;
  end
end

always @ (posedge clk) begin
  if (dcc_en && !dcc_run) begin
    dcc_run <= 1;
    dcc_cntr <= 0;
  end else if (dcc_run && (dcc_cntr == 15)) begin
    dcc_run <= 0;
    dcc_cntr <= 0;
    dcc_finishing <= 1;
  end else if (dcc_finishing && (dcc_cntr == 15)) begin
    dcc_finishing <= 0;
    skip16 <= 1;
  end else if (skip16 && (dcc_cntr == 15)) begin
    skip16 <= 0;
  end else if (dcc_run) begin
    dcc_cntr <= dcc_cntr + 1;
  end
end

endmodule

